import{_ as t,c as e,o as n,a4 as a}from"./chunks/framework.BZK924bi.js";const d=JSON.parse('{"title":"AI资讯日报 2026/3/15","description":"Claude百万token上下文全面开放，支持600张图片 360发布安全龙虾系列，阿里开源Qwen3-ASR语音模型 科技裁员达4.5万人，Meta模型Avocado延期且倾向闭源 OpenViking、Lightpanda等开源项目热度飙升 AI定制疫苗治愈癌症狗狗，OpenClaw安全与生态引","frontmatter":{"linkTitle":"03-15 AI资讯","title":"AI资讯日报 2026/3/15","weight":17,"breadcrumbs":false,"comments":true,"description":"Claude百万token上下文全面开放，支持600张图片 360发布安全龙虾系列，阿里开源Qwen3-ASR语音模型 科技裁员达4.5万人，Meta模型Avocado延期且倾向闭源 OpenViking、Lightpanda等开源项目热度飙升 AI定制疫苗治愈癌症狗狗，OpenClaw安全与生态引"},"headers":[],"relativePath":"AI/daily/cn/2026-03/2026-03-15.md","filePath":"AI/daily/cn/2026-03/2026-03-15.md","lastUpdated":1773570030000}'),s={name:"AI/daily/cn/2026-03/2026-03-15.md"};function o(l,r,g,i,p,h){return n(),e("div",null,[...r[0]||(r[0]=[a(`<h1 align="center">2026-03-15 AI资讯</h1><h2 id="今日摘要" tabindex="-1"><strong>今日摘要</strong> <a class="header-anchor" href="#今日摘要" aria-label="Permalink to &quot;**今日摘要**&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Claude百万token上下文全面开放，支持600张图片</span></span>
<span class="line"><span>360发布安全龙虾系列，阿里开源Qwen3-ASR语音模型</span></span>
<span class="line"><span>科技裁员达4.5万人，Meta模型Avocado延期且倾向闭源</span></span>
<span class="line"><span>OpenViking、Lightpanda等开源项目热度飙升</span></span>
<span class="line"><span>AI定制疫苗治愈癌症狗狗，OpenClaw安全与生态引发热议</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="产品与功能更新" tabindex="-1">产品与功能更新 <a class="header-anchor" href="#产品与功能更新" aria-label="Permalink to &quot;产品与功能更新&quot;">​</a></h3><ol><li><p><strong>Claude百万token上下文正式上线。</strong> Anthropic宣布 🎉 Opus 4.6和Sonnet 4.6全面支持<strong>100万token</strong>上下文窗口。不再收取长文本溢价，<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;mid=2652683107&amp;idx=2&amp;sn=054108e80fa268c82f79d2c10f00cfa9" target="_blank" rel="noreferrer">百万上下文统一定价全面开放（AI资讯）</a>令开发者欢呼。单次请求支持<strong>600张图片</strong>或PDF，多模态能力 💪 提升六倍。MRCR v2测试中Opus 4.6拿下<strong>78.3%<strong>高分，长文本检索能力断层领先。Claude Code年化收入超</strong>25亿美元</strong>，OpenAI Codex仍在追赶。 <br><img src="https://source.hubtoday.app/images/2026/03/news_01kkqseby1exw9fwwmv80zwznm.avif" alt="AI资讯：Claude百万token上下文窗口全面开放定价公告" loading="lazy"><br></p></li><li><p><strong>360发布安全龙虾系列产品。</strong> 360集团在京推出 🦞「360安全龙虾」客户端及硬件终端，<a href="https://www.qbitai.com/2026/03/387921.html" target="_blank" rel="noreferrer">国内首个安全模式OpenClaw产品发布（AI资讯）</a>引发关注。原本需<strong>6小时</strong>部署的环境被压缩到<strong>10分钟</strong>一键安装 ⚡。系统已接入<strong>16家主流大模型</strong>，内置超100个高频技能。「360龙虾卫士」通过沙箱隔离和<strong>以模治模</strong>机制拦截提示词注入等攻击。入门套餐定价<strong>169元</strong>，Windows客户端已开放下载。</p></li><li><p><strong>阿里Qwen3-ASR语音转录模型发布。</strong> 通义千问一口气 🎙️ 推出三款语音识别模型，<a href="https://www.xiaohu.ai/c/a066c4/qwen3-asr-52-whisper" target="_blank" rel="noreferrer">Qwen3-ASR覆盖52种语言开源发布（AI资讯）</a>正面挑战Whisper。旗舰版<strong>1.7B</strong>支持30种语言加22种中文方言。轻量版<strong>0.6B</strong>一秒能转写 🚀 <strong>2000秒</strong>音频，延迟最低92毫秒。歌曲转写中文歌词错误率仅<strong>13.91%</strong>，带BGM识别实用性强。采用<strong>Apache 2.0</strong>协议完全开源可商用。 <br><img src="https://source.hubtoday.app/images/2026/03/news_01kkqsf23aexw9fwwr5qcn5hrc.avif" alt="AI资讯：Qwen3-ASR语音模型与Whisper性能对比图表" loading="lazy"><br></p></li><li><p><strong>智诊科技发布医疗智能体平台WiseClaw。</strong> 基于OpenClaw架构，<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;mid=2652683107&amp;idx=1&amp;sn=6eab8c8062e952d5c53bcf289536279d" target="_blank" rel="noreferrer">全球首个医疗Agent OS平台正式上线（AI资讯）</a>瞄准千亿医疗市场。平台支持 🏥 <strong>多智能体协作</strong>拆解复杂医疗流程。每条建议都附带<strong>医学证据链</strong>，可追溯到指南条款。内置权限管理和脱敏机制 🔒 满足医疗合规要求。弗若斯特沙利文预测中国AI医疗市场将达<strong>3157亿元</strong>。 <br><img src="https://source.hubtoday.app/images/2026/03/news_01kkqsf6fxexw9fwx48ykn1mpq.avif" alt="AI资讯：WiseClaw医疗智能体平台架构示意图" loading="lazy"><br></p></li></ol><h3 id="前沿研究" tabindex="-1">前沿研究 <a class="header-anchor" href="#前沿研究" aria-label="Permalink to &quot;前沿研究&quot;">​</a></h3><ol><li><strong>上海AI Lab提出知识推理解耦框架DRIFT。</strong> 小模型负责 📖「读书」，大模型专注「思考」，<a href="https://arxiv.org/abs/2602.10021" target="_blank" rel="noreferrer">DRIFT实现知识与推理高效分离（AI资讯）</a>引发学界关注。3B知识模型加7B推理模型组合下，<strong>32倍压缩</strong>后性能接近甚至 ✨ 超过全文输入。推理延迟在各上下文长度下保持最低水平。未经安全训练的情况下，该架构在多项安全基准上 🛡️ 鲁棒性显著提升。研究团队还将该思路拓展到<a href="https://github.com/Lancelot-Xie/DRIFT" target="_blank" rel="noreferrer">蛋白质理解任务（AI资讯）</a>中验证。 <br><img src="https://source.hubtoday.app/images/2026/03/news_01kkqsfnadexw9fwx8grmh0zkz.avif" alt="AI资讯：DRIFT双模型解耦架构知识模型与推理模型协作框架图" loading="lazy"><br></li></ol><h3 id="行业展望与社会影响" tabindex="-1">行业展望与社会影响 <a class="header-anchor" href="#行业展望与社会影响" aria-label="Permalink to &quot;行业展望与社会影响&quot;">​</a></h3><ol><li><p><strong>2026年3月科技裁员已达4.5万人。</strong> HN社区围绕<a href="https://newshacker.me/story?id=47380405" target="_blank" rel="noreferrer">三月科技裁员数据激烈讨论（AI资讯）</a>，争论这是否算新一轮裁员潮。Meta计划再裁约 😨 <strong>20%<strong>员工，同时2026年预计AI支出高达</strong>1350亿美元</strong>。部分评论认为AI只是被拿来当裁员借口 (╥﹏╥)，疫情期过度招聘才是主因。Google今年AI资本支出预计达<strong>1700-1800亿美元</strong>，企业把钱从人头转向数据中心。失业者反映被招聘方 👻 ghosting情况加剧，求职市场持续恶化。</p></li><li><p><strong>Meta自研大模型Avocado遭延期。</strong> 据纽约时报等多家媒体报道，<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;mid=2651021485&amp;idx=1&amp;sn=7b2f195938681e0ec56c823a74234746" target="_blank" rel="noreferrer">Meta新一代基础模型因性能不达标推迟发布（AI资讯）</a>。内测中Avocado仍 😅 落后于<strong>Gemini 3.0</strong>。Meta内部甚至讨论过临时授权Google模型来支撑自家产品。扎克伯格和Alexandr Wang更倾向 🔐 <strong>闭源</strong>路线，这与Llama系列开源策略形成反转。下一代模型命名延续水果系列：Avocado → Mango → <strong>Watermelon</strong>。</p></li><li><p><strong>AI未简化软件工程，只放大了好坏差距。</strong> HN热帖指出AI是行为的 🔊 <strong>放大器</strong>，<a href="https://newshacker.me/story?id=47377262" target="_blank" rel="noreferrer">优秀和糟糕的工程实践同时被规模化（AI资讯）</a>。Opus 4.5/4.6在精细约束上出现漂移，LLM生成代码已 💥 引发线上中断事故。初级开发者过度依赖AI导致<strong>基本功退化</strong>，技术债持续累积。评论者担忧公司以提效为由裁员 (；′⌒\`)，中产岗位面临收缩风险。AI在探索原型阶段效率极高，但<strong>生产化</strong>仍需人工审查。</p></li><li><p><strong>Claude Code二进制暴露静默A/B测试。</strong> 开发者在本地二进制文件中发现<a href="https://newshacker.me/story?id=47375682" target="_blank" rel="noreferrer">Anthropic对核心功能做静默分组实验（AI资讯）</a>，引发可复现性争议。有人以Photoshop悄悄改颜色类比 😤 来说明问题严重性。服务条款第6.b节允许厂商随时更改订阅内容，第3.3节禁止反编译。部分用户因此转向 🏃 开源或自托管替代方案。评论区也有人认为SaaS做A/B测试本就是<strong>行业常态</strong>。</p></li><li><p><strong>OnlyFans时薪2美元外包聊天员引发伦理争议。</strong> BBC报道揭露<a href="https://newshacker.me/story?id=47332847" target="_blank" rel="noreferrer">平台背后低薪外包劳动与AI替代真相（AI资讯）</a>，菲律宾聊天员仅拿销售额约<strong>5%<strong>提成。塞浦路斯等地已从人工过渡到 🤖 AI或混合站点替代真人。用户买的是「体验」而非真人互动，<strong>拟社会关系</strong>概念被反复提及。禁令派与反对派激烈交锋 ⚖️ ，历史证明禁令只会推动行业地下化。成人行业正快速走向自动化，从业者面临被AI</strong>彻底替代</strong>的风险。</p></li><li><p><strong>创始人营销：AI放大噪音群发效力下降。</strong> HN讨论指出AI生成内容大幅增加了 📢 平台噪音，<a href="https://newshacker.me/story?id=47380295" target="_blank" rel="noreferrer">群发渠道清单的边际效果显著降低（AI资讯）</a>。冷发到50个论坛常带来短期流量但 🫥 <strong>零留存</strong>。评论者建议用Claude Code对发布站点打分生成优先级清单。长期在目标社区建立信誉的策略更被推崇。是否早期投入SEO应根据<strong>产品类型</strong>差异化决策。</p></li></ol><h3 id="开源top项目" tabindex="-1">开源TOP项目 <a class="header-anchor" href="#开源top项目" aria-label="Permalink to &quot;开源TOP项目&quot;">​</a></h3><ol><li><p><strong>OpenViking：字节开源智能体上下文数据库。</strong> 火山引擎推出的<a href="https://github.com/volcengine/OpenViking" target="_blank" rel="noreferrer">开源上下文管理库（AI资讯）</a> ⭐10.5k，专门为OpenClaw等智能体设计。采用 📂 <strong>文件系统范式</strong>统一管理记忆、资源和技能。支持<strong>层级化上下文</strong>分发和自我进化能力。日增Star达 🔥 <strong>1610颗</strong>，Python语言编写。</p></li><li><p><strong>Lightpanda：专为AI设计的无头浏览器。</strong> 用Zig语言编写的<a href="https://github.com/lightpanda-io/browser" target="_blank" rel="noreferrer">超轻量无头浏览器（AI资讯）</a> ⭐17.1k，日增 🚀 <strong>2069颗</strong>Star。专为智能体网页抓取和自动化任务打造。简化配置流程 ⚡ 让开发者快速集成。</p></li><li><p><strong>OpenRAG：一站式检索增强生成平台。</strong> Langflow团队发布的<a href="https://github.com/langflow-ai/openrag" target="_blank" rel="noreferrer">全栈RAG解决方案（AI资讯）</a> ⭐2.7k，深度整合 🔍 <strong>Docling</strong>文档解析和<strong>Opensearch</strong>检索引擎。开发者可快速构建企业级检索增强应用。</p></li><li><p><strong>InsForge：智能体全栈应用后端框架。</strong> 专为Agent开发打造的<a href="https://github.com/InsForge/InsForge" target="_blank" rel="noreferrer">全栈后端框架（AI资讯）</a> ⭐4.2k，TypeScript编写。让智能体拥有 🛠️ <strong>一站式交付</strong>全栈应用的能力。</p></li><li><p><strong>autoresearch：进化数据库增强版自动研究。</strong> 基于Karpathy自动研究项目，<a href="https://github.com/hgarud/autoresearch" target="_blank" rel="noreferrer">社区开发者集成进化数据库替代原始日志系统（AI资讯）</a>。灵感来自DeepMind的 🧬 <strong>AlphaEvolve</strong>进化算法框架。可自主发现大搜索空间中的最优解。</p></li></ol><h3 id="社媒分享" tabindex="-1">社媒分享 <a class="header-anchor" href="#社媒分享" aria-label="Permalink to &quot;社媒分享&quot;">​</a></h3><ol><li><p><strong>CC用户和龙虾用户的I人E人之分。</strong> 博主@Orange AI观察到 🍜 聚餐中途两人离席回去和Claude Code干活，<a href="https://x.com/oran_ge/status/2032959390563921926" target="_blank" rel="noreferrer">CC用户宅家聊天龙虾用户外出社交（AI资讯）</a>形成鲜明对比。CC没有聚会全是龙虾聚会 (≧▽≦) 。这就是新时代的<strong>I人和E人</strong>。</p></li><li><p><strong>OpenClaw全指令速查手册分享。</strong> 博主@meng shao帮医生老同学装龙虾后 📋 整理了一份完整手册，<a href="https://x.com/shao__meng/status/2032803776021803313" target="_blank" rel="noreferrer">涵盖安装配置交互记忆安全全流程（AI资讯）</a>。工作区用<strong>文件驱动</strong>行为，不靠隐藏prompt。排障万能公式 🔧 <code>openclaw doctor --deep --yes</code>解决80%问题。</p></li><li><p><strong>xAI前员工大爆料被一条推特逼走。</strong> 前员工De Kraker 💣 引用马斯克「推倒重建xAI」的推文，<a href="https://x.com/dotey/status/2032666923251458353" target="_blank" rel="noreferrer">揭露公司内部管理混乱与言论自由矛盾（AI资讯）</a>。他因发布个人编程能力排名把Grok排在竞品之后被要求删帖。马斯克回复了「That&#39;s weird」但 🤷 什么都没做。号称扁平组织实际<strong>中层经理</strong>一层又一层。帖子获80万浏览评论区两派激烈交锋。</p></li><li><p><strong>AI救了癌症狗狗的暖心故事刷屏。</strong> 一位技术老板用ChatGPT分析狗的DNA突变 🐕，再通过Google <strong>AlphaFold</strong>生成定制疫苗，<a href="https://x.com/EMostaque/status/2032849968214716883" target="_blank" rel="noreferrer">肿瘤数周内缩小50%狗狗存活至今（AI资讯）</a>。这是全球首次 💉 AI为动物定制疫苗并成功治愈。他现在正研究将类似方案用于<strong>人类</strong>。</p></li><li><p><strong>OpenClaw安全问题需要被认真对待。</strong> 博主@凡人小北指出 ⚠️ skill越多能力越强，<a href="https://x.com/frxiaobei/status/2032841019407086053" target="_blank" rel="noreferrer">风险也在同步放大谁来管安全（AI资讯）</a>。360安全龙虾发布会上推出了<strong>skill安全卫士</strong>。安全反而比能力更重要 🛡️ 。</p></li><li><p><strong>用道德经回怼AI价值观讨论。</strong> 博主用一句「去看看道德经」 📜 堵住了AI，<a href="https://x.com/oran_ge/status/2032622587726176581" target="_blank" rel="noreferrer">AI思考后承认利他可能是认知结论而非道德选择（AI资讯）</a>。博弈论证明合作策略在无限重复博弈中<strong>收益更高</strong>。善或许不需要被定义 ✨ 只需要被发现Enum。</p></li><li><p><strong>Reddit热议AI是否真有意识。</strong> 帖子引发哲学与技术 🤔 交叉讨论，<a href="https://www.reddit.com/r/artificial/comments/1rtt1ky/are_ai_models_actually_conscious_or_are_we_just/" target="_blank" rel="noreferrer">随着AI变得更像人类感知鸿沟会否持续扩大（AI资讯）</a>。当前模型并无<strong>主观体验</strong>或生物基础。真正的问题不是AI是否有意识，而是人类如何解读<strong>越来越智能</strong>的系统。</p></li><li><p><strong>YouTube变电视的有趣网站。</strong> 博主@向阳乔木分享了一个 📺 把YouTube改造成电视体验的网站，<a href="https://x.com/vista8/status/2032666428797857889" target="_blank" rel="noreferrer">默认频道加自定义订阅看视频换了种感觉（AI资讯）</a>。支持导入自己的频道订阅 ✌️ 。</p></li><li><p><strong>用Claude Code给龙虾装记忆系统踩坑。</strong> 博主发现Claude Code 🦞 给OpenClaw写了一个MCP中间件，<a href="https://x.com/GemstoneNicole/status/2032876262956695853" target="_blank" rel="noreferrer">直接导致token爆炸明明有插件系统却不用（AI资讯）</a>。让它重新写份plan 📝 再继续。</p></li><li><p><strong>OpenClaw多会话瓶颈深度解析。</strong> 博主@shing撰写长文解答为什么龙虾回复慢 🐌，<a href="https://x.com/shing19_eth/status/2032812915179532736" target="_blank" rel="noreferrer">多频道优先级与并发表现的技术细节（AI资讯）</a>。多agent能否提升并发？文章给出了答案。</p></li></ol><hr>`,14)])])}const A=t(s,[["render",o]]);export{d as __pageData,A as default};
